//! `attome sdk generate` (roadmap M17-T3): typed Rust structs and TypeScript
//! interfaces for a deployment's own entities, from its OpenAPI document
//! (`GET /api/v1/openapi/deployment.json`, Y9-T2). Each entity has two
//! schemas there, the record (`deal`) and what a create accepts
//! (`deal_input`); each becomes one Rust struct and one TypeScript interface.
//!
//! The Rust needs only `serde`; identifiers and timestamps stay `String`, so
//! the generated file adds no other dependency to the customer's crate. A
//! choice field's values are a TypeScript union and a doc line in Rust.
//!
//! ```text
//! curl -b cookies.txt https://crm.example.com/api/v1/openapi/deployment.json -o deployment.json
//! attome sdk generate deployment.json --out src/generated
//! ```

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

use serde_json::Value;

/// The two files generated.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Generated {
    pub rust: String,
    pub typescript: String,
}

const RUST_KEYWORDS: &[&str] = &[
    "as", "async", "await", "break", "const", "continue", "crate", "dyn", "else", "enum", "extern",
    "false", "fn", "for", "if", "impl", "in", "let", "loop", "match", "mod", "move", "mut", "pub",
    "ref", "return", "static", "struct", "super", "trait", "true", "type", "unsafe", "use",
    "where", "while", "abstract", "become", "box", "do", "final", "macro", "override", "priv",
    "try", "typeof", "unsized", "virtual", "yield",
];

fn pascal(name: &str) -> String {
    name.split(|c: char| !c.is_ascii_alphanumeric())
        .filter(|part| !part.is_empty())
        .map(|part| {
            let mut chars = part.chars();
            match chars.next() {
                Some(first) => first.to_ascii_uppercase().to_string() + chars.as_str(),
                None => String::new(),
            }
        })
        .collect()
}

fn rust_field(name: &str) -> String {
    let snake: String = name
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() { c } else { '_' })
        .collect();
    if snake.starts_with(|c: char| c.is_ascii_digit()) {
        format!("_{snake}")
    } else if RUST_KEYWORDS.contains(&snake.as_str()) {
        format!("r#{snake}")
    } else {
        snake
    }
}

/// The schema's type and whether it admits null.
fn base_type(schema: &Value) -> (Option<&str>, bool) {
    match &schema["type"] {
        Value::String(t) => (Some(t.as_str()), false),
        Value::Array(types) => {
            let nullable = types.iter().any(|t| t == "null");
            let first = types
                .iter()
                .filter_map(Value::as_str)
                .find(|t| *t != "null");
            (first, nullable)
        }
        _ => (None, false),
    }
}

fn rust_type(schema: &Value) -> String {
    let (ty, nullable) = base_type(schema);
    let inner = match ty {
        Some("string") => "String".to_owned(),
        Some("integer") => "i64".to_owned(),
        Some("number") => "f64".to_owned(),
        Some("boolean") => "bool".to_owned(),
        Some("array") => format!("Vec<{}>", rust_type(&schema["items"])),
        _ => "serde_json::Value".to_owned(),
    };
    if nullable {
        format!("Option<{inner}>")
    } else {
        inner
    }
}

fn ts_type(schema: &Value) -> String {
    let (ty, nullable) = base_type(schema);
    let inner = match ty {
        Some("string") => match schema["enum"].as_array() {
            Some(values) if !values.is_empty() => values
                .iter()
                .filter_map(Value::as_str)
                .map(|v| format!("'{}'", v.replace('\\', "\\\\").replace('\'', "\\'")))
                .collect::<Vec<_>>()
                .join(" | "),
            _ => "string".to_owned(),
        },
        Some("integer") | Some("number") => "number".to_owned(),
        Some("boolean") => "boolean".to_owned(),
        Some("array") => format!("Array<{}>", ts_type(&schema["items"])),
        _ => "unknown".to_owned(),
    };
    if nullable {
        format!("{inner} | null")
    } else {
        inner
    }
}

fn ts_key(name: &str) -> String {
    if !name.is_empty()
        && name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
        && !name.starts_with(|c: char| c.is_ascii_digit())
    {
        name.to_owned()
    } else {
        format!("'{}'", name.replace('\'', "\\'"))
    }
}

/// Generates both files from a deployment OpenAPI document.
pub fn generate(document: &Value, source: &str) -> Result<Generated, String> {
    let schemas = document["components"]["schemas"]
        .as_object()
        .ok_or("the document has no components.schemas; is it the deployment document?")?;
    let header = format!("Generated by `attome sdk generate` from {source}. Do not edit.");
    let mut rust =
        format!("// {header}\n\n#![allow(dead_code)]\n\nuse serde::{{Deserialize, Serialize}};\n");
    let mut typescript = format!("// {header}\n");
    let mut names: Vec<&String> = schemas.keys().collect();
    names.sort();
    for name in names {
        let schema = &schemas[name];
        let Some(properties) = schema["properties"].as_object() else {
            continue;
        };
        let required: Vec<&str> = schema["required"]
            .as_array()
            .map(|r| r.iter().filter_map(Value::as_str).collect())
            .unwrap_or_default();
        let type_name = pascal(name);
        let mut fields: Vec<&String> = properties.keys().collect();
        fields.sort();

        let _ = write!(
            rust,
            "\n/// `{name}`.\n#[derive(Debug, Clone, Default, Serialize, Deserialize)]\npub struct {type_name} {{\n"
        );
        let _ = write!(
            typescript,
            "\n/** `{name}`. */\nexport interface {type_name} {{\n"
        );
        for field in fields {
            let property = &properties[field];
            let is_required = required.contains(&field.as_str());
            if let Some(values) = property["enum"].as_array() {
                let list: Vec<&str> = values.iter().filter_map(Value::as_str).collect();
                let _ = writeln!(rust, "    /// One of: {}.", list.join(", "));
            }
            let ident = rust_field(field);
            let mut ty = rust_type(property);
            if !is_required && !ty.starts_with("Option<") {
                ty = format!("Option<{ty}>");
            }
            if ident.trim_start_matches("r#") != field.as_str() {
                let _ = writeln!(rust, "    #[serde(rename = \"{field}\")]");
            }
            if ty.starts_with("Option<") {
                let _ = writeln!(
                    rust,
                    "    #[serde(default, skip_serializing_if = \"Option::is_none\")]"
                );
            }
            let _ = writeln!(rust, "    pub {ident}: {ty},");
            let optional = if is_required { "" } else { "?" };
            let _ = writeln!(
                typescript,
                "  {}{optional}: {};",
                ts_key(field),
                ts_type(property)
            );
        }
        rust.push_str("}\n");
        typescript.push_str("}\n");
    }
    Ok(Generated { rust, typescript })
}

/// Reads `input`, writes `attome_entities.rs` and `attome-entities.ts` into
/// `out`; answers the two paths.
pub fn run(input: &Path, out: &Path) -> Result<(PathBuf, PathBuf), String> {
    let text =
        std::fs::read_to_string(input).map_err(|e| format!("read {}: {e}", input.display()))?;
    let document: Value =
        serde_json::from_str(&text).map_err(|e| format!("{} is not JSON: {e}", input.display()))?;
    let source = input.file_name().map_or_else(
        || input.display().to_string(),
        |n| n.to_string_lossy().into_owned(),
    );
    let generated = generate(&document, &source)?;
    std::fs::create_dir_all(out).map_err(|e| format!("create {}: {e}", out.display()))?;
    let rust = out.join("attome_entities.rs");
    let typescript = out.join("attome-entities.ts");
    std::fs::write(&rust, generated.rust).map_err(|e| format!("write {}: {e}", rust.display()))?;
    std::fs::write(&typescript, generated.typescript)
        .map_err(|e| format!("write {}: {e}", typescript.display()))?;
    Ok((rust, typescript))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn fixture() -> Value {
        serde_json::json!({
            "openapi": "3.1.0",
            "components": { "schemas": {
                "deal": {
                    "type": "object",
                    "properties": {
                        "id": { "type": "string", "format": "uuid" },
                        "row_version": { "type": "integer" },
                        "amount": { "type": "number" },
                        "stage": { "type": "string", "enum": ["open", "won"] },
                        "closed_at": { "type": ["string", "null"], "format": "date-time" },
                        "type": { "type": "string" },
                        "tags": { "type": "array", "items": { "type": "string" } }
                    }
                },
                "deal_input": {
                    "type": "object",
                    "properties": {
                        "name": { "type": "string" },
                        "amount": { "type": "number" }
                    },
                    "required": ["name"]
                }
            } }
        })
    }

    #[test]
    fn entities_become_rust_structs() {
        let generated = generate(&fixture(), "deployment.json").unwrap();
        let rust = &generated.rust;
        assert!(rust.contains("pub struct Deal {"), "{rust}");
        assert!(rust.contains("pub struct DealInput {"), "{rust}");
        assert!(rust.contains("pub amount: Option<f64>,"), "{rust}");
        assert!(
            rust.contains("pub name: String,"),
            "required stays plain: {rust}"
        );
        assert!(rust.contains("pub closed_at: Option<String>,"), "{rust}");
        assert!(
            rust.contains("pub r#type: Option<String>,"),
            "keywords are raw: {rust}"
        );
        assert!(rust.contains("pub tags: Option<Vec<String>>,"), "{rust}");
        assert!(rust.contains("/// One of: open, won."), "{rust}");
    }

    #[test]
    fn entities_become_typescript_interfaces() {
        let ts = generate(&fixture(), "deployment.json").unwrap().typescript;
        assert!(ts.contains("export interface Deal {"), "{ts}");
        assert!(ts.contains("  stage?: 'open' | 'won';"), "{ts}");
        assert!(ts.contains("  closed_at?: string | null;"), "{ts}");
        assert!(ts.contains("  name: string;"), "{ts}");
        assert!(ts.contains("  tags?: Array<string>;"), "{ts}");
    }

    #[test]
    fn a_document_without_schemas_is_refused() {
        assert!(generate(&serde_json::json!({ "openapi": "3.1.0" }), "x").is_err());
    }
}
